const { chromium } = require('playwright');
const O = process.env.OUT || __dirname + '/';
const URL = process.env.URL || 'http://localhost:8765/';
const DSF = +(process.env.DSF || 1);
(async () => {
  const b = await chromium.launch(); const errs = [];
  const c = await b.newContext({ viewport: { width: 390, height: 844 }, deviceScaleFactor: DSF, timezoneId: 'Europe/Istanbul' });
  await c.addInitScript(() => { if (!localStorage.getItem('x')) { localStorage.setItem('x','1'); localStorage.setItem('gezi-acilis-gordu','1'); localStorage.setItem('gezi-tanitim','1'); localStorage.setItem('gezi-yenilik','6.5.1'); localStorage.setItem('gezi-dil','tr'); localStorage.setItem('gezi-anma-soru','1'); localStorage.setItem('gezi-puan', JSON.stringify({ n: 1, bitti: true })); } sessionStorage.setItem('gezi-acilis-atla','1'); });
  const p = await c.newPage();
  p.on('pageerror', e => errs.push(e.message));
  const bekle = (ms) => p.waitForTimeout(ms);
  await p.goto(URL); await bekle(3000);
  await p.evaluate(() => { const e = document.getElementById('planBtn'); window.scrollTo(0, e.getBoundingClientRect().top + scrollY - 150); }); await bekle(1500);
  await p.screenshot({ path: O + '01-ana.png' });
  await p.click('.tarz[data-go="#/tarz/deniz"]'); await bekle(2500);
  console.log('deniz', await p.textContent('#temaSay'), (await p.$$eval('#temaList li', l => l.slice(0, 6).map(x => x.innerText.split('\n')[0]))).join(' | '));
  await p.screenshot({ path: O + '02-deniz.png' });
  await p.click('#tarzChips [data-tarz=doga]'); await bekle(1500);
  console.log('doga', await p.textContent('#temaSay'), await p.isVisible('#temaMore'));
  await p.screenshot({ path: O + '03-doga.png' });
  await p.goto(URL + '#/plan'); await bekle(1000);
  await p.screenshot({ path: O + '04-plan-bos.png' });
  await p.click('[data-p=yeni]'); await bekle(500);
  await p.fill('#plAd', 'Akdeniz tatili');
  await p.click('#plParca [data-k=kon]'); await bekle(400);
  await p.screenshot({ path: O + '05-nereye.png' });
  await p.fill('#knAra', 'izmir'); await bekle(500);
  await p.click('#knList [data-i="0"]'); await bekle(400);
  await p.click('#plParca [data-k=az]');
  await p.click('[data-k=sehirekle]'); await bekle(400);
  await p.fill('#knAra', 'fethiye'); await bekle(800);
  console.log('fethiye', (await p.$$eval('#knList li', l => l.slice(0, 4).map(x => x.innerText.replace(/\n/g, ' / ')))).join(' | '));
  await p.screenshot({ path: O + '06-fethiye-ara.png' });
  await p.click('#knList [data-i="0"]'); await bekle(400);
  await p.click('[data-k=sehirekle]'); await bekle(400);
  await p.fill('#knAra', 'kaputaş'); await bekle(800);
  console.log('kaputas', (await p.$$eval('#knList li', l => l.slice(0, 3).map(x => x.innerText.replace(/\n/g, ' / ')))).join(' | '));
  await p.click('#knList [data-i="0"]'); await bekle(400);
  await p.click('#plParca .plparca:nth-child(3) [data-k=cok]');
  await p.screenshot({ path: O + '07-yeni-plan.png' });
  await p.click('[data-k=tamam]'); await bekle(1000);
  await p.click('[data-p=ekle][data-g="0"]'); await bekle(2500);
  console.log('oneri', await p.textContent('#plBas'), (await p.$$eval('#plSonuc li', l => l.slice(0, 5).map(x => x.innerText.split('\n')[0]))).join(' | '));
  for (const r of (await p.$$('#plSonuc .plsatir')).slice(0, 3)) { await r.click(); await bekle(300); }
  await bekle(1500);
  await p.screenshot({ path: O + '08-yer-ekle.png' });
  await p.click('.tanit [data-k=kapat]'); await bekle(600);
  await p.click('[data-p=ekle][data-g="2"]'); await bekle(2000);
  for (const r of (await p.$$('#plSonuc .plsatir')).slice(0, 2)) { await r.click(); await bekle(300); }
  await p.click('.tanit [data-k=kapat]'); await bekle(600);
  await p.click('[data-p=ekle][data-g="4"]'); await bekle(2000);
  for (const r of (await p.$$('#plSonuc .plsatir')).slice(0, 3)) { await r.click(); await bekle(300); }
  await p.click('.tanit [data-k=kapat]'); await bekle(600);
  await p.click('[data-p=asagi][data-g="0"][data-i="0"]'); await bekle(2500);
  await p.screenshot({ path: O + '09-plan-ust.png' });
  await p.screenshot({ path: O + '10-plan-tam.png', fullPage: true });
  console.log('plan', JSON.stringify(await p.evaluate(() => JSON.parse(localStorage.getItem('gezi-plan'))[0].kon.map(k => k && k.ad))));
  await p.goto(URL + '#/plan'); await bekle(1500);
  await p.screenshot({ path: O + '11-planlar.png' });
  await p.goto(URL + '#/il/nevsehir'); await bekle(2500);
  await p.click('#list .row'); await bekle(1500);
  await p.evaluate(() => document.querySelector('#sheet .eylem').scrollIntoView({ block: 'center' })); await bekle(800);
  await p.screenshot({ path: O + '12a-detay.png' });
  await p.click('#dPlan'); await bekle(600);
  await p.screenshot({ path: O + '12-plana-ekle.png' });
  await p.click('.tanit [data-id][data-g="3"]'); await bekle(500);
  await p.goto(URL + '#/rozetler'); await bekle(2500);
  await p.screenshot({ path: O + '13-gezilerim-soru.png' });
  await p.click('#isaretSor [data-k=evet]'); await bekle(1000);
  await p.screenshot({ path: O + '14-isaret-mod.png' });
  await p.click('#gezHarita path[data-go="#/il/konya"]', { force: true }); await bekle(2500);
  for (const r of (await p.$$('#isList .plsatir')).slice(0, 3)) { await r.click(); await bekle(250); }
  await p.screenshot({ path: O + '15-il-sec.png' });
  await p.click('.tanit [data-k=kapat]'); await bekle(1500);
  await p.click('#gezHarita path[data-go="#/il/mugla"]', { force: true }); await bekle(2500);
  for (const r of (await p.$$('#isList .plsatir')).slice(0, 2)) { await r.click(); await bekle(250); }
  await p.click('.tanit [data-k=kapat]'); await bekle(1500);
  console.log('hash', await p.evaluate(() => location.hash), await p.textContent('#gezSay'));
  await p.evaluate(() => document.getElementById('gezHarita').scrollIntoView({ block: 'start' })); await bekle(400);
  await p.screenshot({ path: O + '16-harita.png' });
  console.log('gittim', await p.evaluate(() => JSON.parse(localStorage.getItem('gezi-gittim')).map(x => x.ad + ':' + x.t).join(', ')));
  console.log('pageerrors', errs.length, errs.slice(0, 5).join(' | '));
  await b.close();
})();
